inputs.manifest:
{
  "schema_version": "1.0.0",
  "id": "krea2/img2img",
  "label": {
    "en": "Image to Image",
    "ru": "Image to Image"
  },
  "family": "krea2",
  "family_label": "Krea 2 Turbo",
  "tier": 3,
  "mode": "img2img",
  "order": 15,
  "controls": [
    {
      "param": "prompt",
      "kind": "prompt",
      "superprompt": true
    },
    {
      "param": "megapixels",
      "kind": "slider",
      "min": 0.5,
      "max": 4.0,
      "step": 0.1,
      "label": {
        "en": "Resolution",
        "ru": "Разрешение"
      },
      "tooltip": {
        "en": "Megapixels the picture is resampled to before the model sees it. The aspect ratio is kept; sides are snapped to what this model needs.",
        "ru": "До скольких мегапикселей картинка пересчитывается перед моделью. Пропорция сохраняется, стороны округляются под требования модели."
      }
    },
    {
      "param": "denoise",
      "kind": "slider",
      "min": 0.05,
      "max": 0.6,
      "step": 0.05,
      "default": 0.35,
      "label": {
        "en": "Detail denoise",
        "ru": "Денойз деталей"
      },
      "tooltip": {
        "en": "How much the pass invents. 0.2-0.3 stays faithful to the source; 0.45 adds noticeable new detail - good at 1x and 2x, heavy-handed when enlarging fourfold.",
        "ru": "Насколько проход домысливает. 0.2–0.3 — верность исходнику; 0.45 заметно добавляет деталей: хорошо для 1x и 2x, многовато при увеличении вчетверо."
      }
    },
    {
      "param": "loras",
      "kind": "loras",
      "max": 8,
      "strength": [
        -2.0,
        2.0
      ]
    },
    {
      "param": "steps",
      "kind": "number",
      "advanced": true,
      "min": 1,
      "max": 30,
      "default": 8,
      "label": {
        "en": "Steps",
        "ru": "Шаги"
      }
    }
  ],
  "refs": {
    "max": 0
  },
  "requires": [
    "source_image"
  ],
  "upscale_params": {
    "image": "source_image"
  },
  "negative_prompt": false,
  "models": [
    {
      "title": "studio:model",
      "input": "unet_name",
      "folder": "diffusion_models",
      "match": "krea2_turbo_int8_convrot"
    },
    {
      "title": "studio:clip",
      "input": "clip_name",
      "folder": "text_encoders",
      "match": "Qwen3-VL-4B-Instruct-abliterated_int8"
    },
    {
      "title": "studio:vae",
      "input": "vae_name",
      "folder": "vae",
      "match": "qwen_image_vae"
    }
  ],
  "_note_seed": "Сида в деке нет намеренно: апскейл повторяют не ради того же зерна, а ради другого. Маркер `p_seed` в графе остался, и на каждый прогон приходит новое число — то же самое, что «Randomize» на постоянку.",
  "tuning": {
    "snap_px": 64
  }
}
